package com.example.discussions.exception;import org.springframework.http.HttpStatus;public class ApiException extends RuntimeException{public final HttpStatus status;public ApiException(HttpStatus status,String message){super(message);this.status=status;}public static ApiException notFound(String m){return new ApiException(HttpStatus.NOT_FOUND,m);}public static ApiException forbidden(){return new ApiException(HttpStatus.FORBIDDEN,"Недостаточно прав");}}
